      mode: o.mode === 'free' ? 'free' : 'focus', owner: Store.tab, elapsedSec: 0, checkpointAt: now,
      startedAt: now, day, promised: r.total, streakPct: r.streakPct, streakDays: r.streakDays, returnPct: r.returnPct,
